// Exercises the built candidate through Vite's production preview.
import { resolve } from "node:path";
const root = resolve("docs/website");
process.chdir(root);
// The candidate checkout is allocated at runtime; resolve its own Vite installation.
const { preview } = await import(Bun.resolveSync("vite", root));
const server = await preview({ root, preview: { host: "127.0.0.1", port: 0, open: false } });
try {
  const address = server.httpServer.address();
  if (!address || typeof address === "string") throw new Error("Preview has no TCP address");
  const base = `http://127.0.0.1:${address.port}/dotfiles`;
  for (const [route, expected] of [
    ["/", "Evidence and feedback"],
    ["/bundles/developer/skill/collect-feedback/how-to/", "Collect evidence and save feedback"],
    ["/bundles/developer/skill/collect-evidence/how-to/", "Collect a web image for feedback"],
  ]) {
    const response = await fetch(base + route);
    const html = await response.text();
    if (!response.ok || !html.includes(expected)) throw new Error(`Route failed: ${route} ${response.status}`);
    if (route.includes("collect-feedback") && (!html.includes("references/cli.md") || !html.includes("references/system.md") || !html.includes("assets/howto/saved-box-note.png"))) throw new Error("Feedback guide lost reference or screenshot links");
    console.log(JSON.stringify({ route, status: response.status, expected, passed: true }));
  }
} finally {
  const closed = Promise.withResolvers<void>();
  server.httpServer.close(() => closed.resolve());
  await closed.promise;
}
process.exit(0);
